mapper.select:
SELECT sc.id, sc.student_id, sc.course_id, sc.exam_type, sc.score, sc.exam_date,
       sc.create_time, s.student_no, s.name AS student_name, c.course_name
FROM score sc
LEFT JOIN student s ON sc.student_id = s.id
LEFT JOIN course c ON sc.course_id = c.id AND c.is_deleted = 0
WHERE sc.is_deleted = 0
  AND sc.course_id = #{courseId}
  AND s.class_id = #{classId}

    AND sc.exam_type = #{examType}

ORDER BY s.student_no
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM score sc
LEFT JOIN student s ON sc.student_id = s.id
WHERE sc.is_deleted = 0
  AND sc.course_id = #{courseId}
  AND s.class_id = #{classId}

    AND sc.exam_type = #{examType}
